package ru.mtuci.drivenext.presentation.landlord
import android.content.Intent; import android.os.Bundle; import android.widget.ArrayAdapter; import androidx.appcompat.app.AppCompatActivity; import ru.mtuci.drivenext.databinding.ActivityCarInfoBinding; import ru.mtuci.drivenext.presentation.common.afterTextChanged
class CarInfoActivity:AppCompatActivity(){override fun onCreate(s:Bundle?){super.onCreate(s);val b=ActivityCarInfoBinding.inflate(layoutInflater);setContentView(b.root);b.transmissionSpinner.adapter=ArrayAdapter(this,android.R.layout.simple_spinner_dropdown_item,listOf("Выберите трансмиссию","Автоматическая","Механическая","Робот","Вариатор"));fun update(){b.sendButton.isEnabled=listOf(b.yearInput,b.brandInput,b.modelInput,b.mileageInput,b.descriptionInput).all{it.text.isNotBlank()}&&b.transmissionSpinner.selectedItemPosition>0};listOf(b.yearInput,b.brandInput,b.modelInput,b.mileageInput,b.descriptionInput).forEach{it.afterTextChanged(::update)};b.transmissionSpinner.onItemSelectedListener=object:android.widget.AdapterView.OnItemSelectedListener{override fun onItemSelected(p:android.widget.AdapterView<*>?,v:android.view.View?,pos:Int,id:Long)=update();override fun onNothingSelected(p:android.widget.AdapterView<*>?)=Unit};b.backButton.setOnClickListener{finish()};b.sendButton.setOnClickListener{startActivity(Intent(this,CarPhotosActivity::class.java))}}}
